-- Every metric of the GASP SaaS core example for the period 2026-01-01 to 2026-06-30, over the tables in data.sql.
-- A direct metric is its OSSIE_SQL_2026 expression with each aggregate evaluated over its dataset's rows for the period
-- (snapshot rows on the period end, event and fact rows dated in the period), as the query layer would. A staged
-- metric reads its staged dataset's row for the period; the subquery is that dataset's source in the model.
-- Standard SQL; runs on DuckDB and Postgres. expected.sql holds the values this returns.
SELECT metric, value
FROM (
  -- gasp_mrr (direct): sum(field.mrr where field.subscription_status = 'active') at period_end
  SELECT 'gasp_mrr' AS metric, (COALESCE((SELECT SUM(subscription.mrr) FILTER (WHERE subscription.subscription_status = 'active') FROM gasp.subscription WHERE snapshot_date = DATE '2026-06-30'), 0)) AS value
  UNION ALL
  -- gasp_arr (direct): metric.mrr * 12
  SELECT 'gasp_arr' AS metric, (((COALESCE((SELECT SUM(subscription.mrr) FILTER (WHERE subscription.subscription_status = 'active') FROM gasp.subscription WHERE snapshot_date = DATE '2026-06-30'), 0)) * 12)) AS value
  UNION ALL
  -- gasp_arr_o (staged): (metric.mrr - window(sum(field.mrr_change where field.expansion_classification in ('pricing_adjustment', 'recontracting')), 12 month)) * 12 over cohort(field.customer_id, period_end)
  SELECT 'gasp_arr_o' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, (((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active'))) - (SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= ((p.period_end + INTERVAL '1 day') - INTERVAL '12 month') AND event_date <= p.period_end AND expansion_classification IN ('pricing_adjustment', 'recontracting') AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active'))) * 12)) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_arr_m (direct): metric.mrr * 12
  SELECT 'gasp_arr_m' AS metric, (((COALESCE((SELECT SUM(subscription.mrr) FILTER (WHERE subscription.subscription_status = 'active') FROM gasp.subscription WHERE snapshot_date = DATE '2026-06-30'), 0)) * 12)) AS value
  UNION ALL
  -- gasp_arpa (direct): metric.mrr / metric.total_customers
  SELECT 'gasp_arpa' AS metric, ((CAST((COALESCE((SELECT SUM(subscription.mrr) FILTER (WHERE subscription.subscription_status = 'active') FROM gasp.subscription WHERE snapshot_date = DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT customer.customer_id) FILTER (WHERE customer.customer_status = 'active') FROM gasp.customer WHERE snapshot_date = DATE '2026-06-30')), 0))) AS value
  UNION ALL
  -- gasp_total_customers (direct): count_distinct(field.customer_id where field.customer_status = 'active') at period_end
  SELECT 'gasp_total_customers' AS metric, ((SELECT COUNT(DISTINCT customer.customer_id) FILTER (WHERE customer.customer_status = 'active') FROM gasp.customer WHERE snapshot_date = DATE '2026-06-30')) AS value
  UNION ALL
  -- gasp_new_customers (direct): count_distinct(field.customer_id where field.event_type = 'new')
  SELECT 'gasp_new_customers' AS metric, ((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')) AS value
  UNION ALL
  -- gasp_churned_customers (direct): count_distinct(field.customer_id where field.event_type = 'churn')
  SELECT 'gasp_churned_customers' AS metric, ((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'churn') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')) AS value
  UNION ALL
  -- gasp_mrr_growth_rate (staged): (metric.mrr - lag(metric.mrr, 1 month)) / lag(metric.mrr, 1 month)
  SELECT 'gasp_mrr_growth_rate' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) - ((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = (((p.period_end + INTERVAL '1 day') - INTERVAL '1 month') - INTERVAL '1 day') AND subscription_status = 'active'))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = (((p.period_end + INTERVAL '1 day') - INTERVAL '1 month') - INTERVAL '1 day') AND subscription_status = 'active')), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_new_mrr (direct): sum(field.mrr_change where field.event_type = 'new')
  SELECT 'gasp_new_mrr' AS metric, (COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS value
  UNION ALL
  -- gasp_expansion_mrr (direct): sum(field.mrr_change where field.event_type = 'expansion')
  SELECT 'gasp_expansion_mrr' AS metric, (COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'expansion') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS value
  UNION ALL
  -- gasp_churned_mrr (direct): -sum(field.mrr_change where field.event_type = 'churn')
  SELECT 'gasp_churned_mrr' AS metric, ((-COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'churn') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0))) AS value
  UNION ALL
  -- gasp_contraction_mrr (direct): -sum(field.mrr_change where field.event_type = 'contraction')
  SELECT 'gasp_contraction_mrr' AS metric, ((-COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'contraction') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0))) AS value
  UNION ALL
  -- gasp_reactivation_mrr (direct): sum(field.mrr_change where field.event_type = 'reactivation')
  SELECT 'gasp_reactivation_mrr' AS metric, (COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'reactivation') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS value
  UNION ALL
  -- gasp_carry_mrr (staged): metric.mrr at period_start - metric.churned_mrr - metric.contraction_mrr
  SELECT 'gasp_carry_mrr' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, (((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn')))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction'))))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_net_new_mrr (direct): metric.new_mrr + metric.expansion_mrr + metric.reactivation_mrr - metric.churned_mrr - metric.contraction_mrr
  SELECT 'gasp_net_new_mrr' AS metric, ((((((COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) + (COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'expansion') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0))) + (COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'reactivation') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0))) - ((-COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'churn') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)))) - ((-COALESCE((SELECT SUM(revenue_event.mrr_change) FILTER (WHERE revenue_event.event_type = 'contraction') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0))))) AS value
  UNION ALL
  -- gasp_nrr (staged): (metric.mrr at period_start + metric.expansion_mrr - metric.contraction_mrr - metric.churned_mrr) / metric.mrr at period_start over cohort(field.customer_id, period_start)
  SELECT 'gasp_nrr' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))) + ((SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'expansion' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active')))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_nrr_o (staged): (metric.mrr at period_start + sum(field.mrr_change where field.event_type = 'expansion' and field.expansion_classification in ('same_product', 'usage_realisation')) - metric.contraction_mrr - metric.churned_mrr) / metric.mrr at period_start over cohort(field.customer_id, period_start)
  SELECT 'gasp_nrr_o' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))) + (SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND (event_type = 'expansion' AND expansion_classification IN ('same_product', 'usage_realisation')) AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_nrr_m (staged): (metric.mrr at period_start + sum(field.mrr_change where field.event_type in ('expansion', 'reactivation') and field.expansion_classification in ('same_product', 'new_module', 'new_buying_centre', 'pricing_adjustment', 'recontracting', 'usage_realisation')) - metric.contraction_mrr - metric.churned_mrr) / metric.mrr at period_start over cohort(field.customer_id, period_start)
  SELECT 'gasp_nrr_m' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))) + (SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND (event_type IN ('expansion', 'reactivation') AND expansion_classification IN ('same_product', 'new_module', 'new_buying_centre', 'pricing_adjustment', 'recontracting', 'usage_realisation')) AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_grr (staged): (metric.mrr at period_start - metric.contraction_mrr - metric.churned_mrr) / metric.mrr at period_start over cohort(field.customer_id, period_start)
  SELECT 'gasp_grr' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST(((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) - ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active' AND customer_id IN (SELECT customer_id FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active'))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_logo_churn_rate (staged): metric.churned_customers / metric.total_customers at period_start
  SELECT 'gasp_logo_churn_rate' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST(((SELECT COUNT(DISTINCT customer_id) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn')) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.customer WHERE snapshot_date = p.period_start AND customer_status = 'active')), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_revenue_churn_rate (staged): (metric.churned_mrr + metric.contraction_mrr) / metric.mrr at period_start
  SELECT 'gasp_revenue_churn_rate' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn'))) + ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction')))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_nps (direct): (count(field.nps_score where field.survey_type = 'customer' and field.nps_score >= 9) - count(field.nps_score where field.survey_type = 'customer' and field.nps_score <= 6)) / count(field.nps_score where field.survey_type = 'customer') * 100
  SELECT 'gasp_nps' AS metric, (((CAST(((SELECT COUNT(survey_response.nps_score) FILTER (WHERE (survey_response.survey_type = 'customer' AND survey_response.nps_score >= 9)) FROM gasp.survey_response WHERE survey_date >= DATE '2026-01-01' AND survey_date <= DATE '2026-06-30') - (SELECT COUNT(survey_response.nps_score) FILTER (WHERE (survey_response.survey_type = 'customer' AND survey_response.nps_score <= 6)) FROM gasp.survey_response WHERE survey_date >= DATE '2026-01-01' AND survey_date <= DATE '2026-06-30')) AS DECIMAL) / NULLIF((SELECT COUNT(survey_response.nps_score) FILTER (WHERE survey_response.survey_type = 'customer') FROM gasp.survey_response WHERE survey_date >= DATE '2026-01-01' AND survey_date <= DATE '2026-06-30'), 0)) * 100)) AS value
  UNION ALL
  -- gasp_cac (direct): sum(field.cost where field.cost_function = 'gtm') / metric.new_customers
  SELECT 'gasp_cac' AS metric, ((CAST(COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'gtm') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')), 0))) AS value
  UNION ALL
  -- gasp_cac_o (direct): (sum(field.cost where field.cost_function = 'gtm') + sum(field.cost where field.cost_function in ('implementation', 'onboarding'))) / metric.new_customers
  SELECT 'gasp_cac_o' AS metric, ((CAST((COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'gtm') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0) + COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function IN ('implementation', 'onboarding')) FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')), 0))) AS value
  UNION ALL
  -- gasp_cac_m (direct): sum(field.cost where field.cost_function = 'gtm') / metric.new_customers
  SELECT 'gasp_cac_m' AS metric, ((CAST(COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'gtm') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')), 0))) AS value
  UNION ALL
  -- gasp_ltv (staged): metric.arpa * metric.gross_margin / metric.revenue_churn_rate
  SELECT 'gasp_ltv' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((CAST(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active')), 0))) * ((CAST(((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'infrastructure')) AS DOUBLE PRECISION) / NULLIF((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end), 0)))) AS DOUBLE PRECISION) / NULLIF(((CAST((((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn'))) + ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction')))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')), 0))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_ltv_o (staged): metric.arpa * metric.gross_margin.O / metric.revenue_churn_rate
  SELECT 'gasp_ltv_o' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((CAST(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active')), 0))) * ((CAST((((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'infrastructure')) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function IN ('support', 'success_engineering', 'implementation', 'onboarding'))) AS DOUBLE PRECISION) / NULLIF((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end), 0)))) AS DOUBLE PRECISION) / NULLIF(((CAST((((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn'))) + ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction')))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')), 0))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_ltv_m (staged): metric.arpa * metric.gross_margin / metric.revenue_churn_rate
  SELECT 'gasp_ltv_m' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST((((CAST(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active')), 0))) * ((CAST(((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'infrastructure')) AS DOUBLE PRECISION) / NULLIF((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end), 0)))) AS DOUBLE PRECISION) / NULLIF(((CAST((((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn'))) + ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction')))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')), 0))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_ltv_cac_ratio (staged): metric.ltv / metric.cac
  SELECT 'gasp_ltv_cac_ratio' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST(((CAST((((CAST(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active')), 0))) * ((CAST(((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'infrastructure')) AS DOUBLE PRECISION) / NULLIF((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end), 0)))) AS DOUBLE PRECISION) / NULLIF(((CAST((((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn'))) + ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction')))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')), 0))), 0))) AS DOUBLE PRECISION) / NULLIF(((CAST((SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'gtm') AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'new')), 0))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_ltv_cac_ratio_o (staged): metric.ltv.O / metric.cac.O
  SELECT 'gasp_ltv_cac_ratio_o' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST(((CAST((((CAST(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active')), 0))) * ((CAST((((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'infrastructure')) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function IN ('support', 'success_engineering', 'implementation', 'onboarding'))) AS DOUBLE PRECISION) / NULLIF((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end), 0)))) AS DOUBLE PRECISION) / NULLIF(((CAST((((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn'))) + ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction')))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')), 0))), 0))) AS DOUBLE PRECISION) / NULLIF(((CAST(((SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'gtm') + (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function IN ('implementation', 'onboarding'))) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'new')), 0))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_ltv_cac_ratio_m (staged): metric.ltv.M / metric.cac.M
  SELECT 'gasp_ltv_cac_ratio_m' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, ((CAST(((CAST((((CAST(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.customer WHERE snapshot_date = p.period_end AND customer_status = 'active')), 0))) * ((CAST(((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end) - (SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'infrastructure')) AS DOUBLE PRECISION) / NULLIF((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end), 0)))) AS DOUBLE PRECISION) / NULLIF(((CAST((((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'churn'))) + ((-(SELECT COALESCE(SUM(mrr_change), 0) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'contraction')))) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_start AND subscription_status = 'active')), 0))), 0))) AS DOUBLE PRECISION) / NULLIF(((CAST((SELECT COALESCE(SUM(cost), 0) FROM gasp.cost_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND cost_function = 'gtm') AS DOUBLE PRECISION) / NULLIF(((SELECT COUNT(DISTINCT customer_id) FROM gasp.revenue_event WHERE event_date >= p.period_start AND event_date <= p.period_end AND event_type = 'new')), 0))), 0))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
  UNION ALL
  -- gasp_cac_payback (direct): metric.cac / (metric.arpa * metric.gross_margin)
  SELECT 'gasp_cac_payback' AS metric, ((CAST(((CAST(COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'gtm') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')), 0))) AS DECIMAL) / NULLIF((((CAST((COALESCE((SELECT SUM(subscription.mrr) FILTER (WHERE subscription.subscription_status = 'active') FROM gasp.subscription WHERE snapshot_date = DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT customer.customer_id) FILTER (WHERE customer.customer_status = 'active') FROM gasp.customer WHERE snapshot_date = DATE '2026-06-30')), 0))) * ((CAST((COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'infrastructure') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0), 0)))), 0))) AS value
  UNION ALL
  -- gasp_cac_payback_o (direct): metric.cac.O / (metric.arpa * metric.gross_margin.O)
  SELECT 'gasp_cac_payback_o' AS metric, ((CAST(((CAST((COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'gtm') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0) + COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function IN ('implementation', 'onboarding')) FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')), 0))) AS DECIMAL) / NULLIF((((CAST((COALESCE((SELECT SUM(subscription.mrr) FILTER (WHERE subscription.subscription_status = 'active') FROM gasp.subscription WHERE snapshot_date = DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT customer.customer_id) FILTER (WHERE customer.customer_status = 'active') FROM gasp.customer WHERE snapshot_date = DATE '2026-06-30')), 0))) * ((CAST(((COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'infrastructure') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function IN ('support', 'success_engineering', 'implementation', 'onboarding')) FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0), 0)))), 0))) AS value
  UNION ALL
  -- gasp_cac_payback_m (direct): metric.cac.M / (metric.arpa * metric.gross_margin.M)
  SELECT 'gasp_cac_payback_m' AS metric, ((CAST(((CAST(COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'gtm') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT revenue_event.customer_id) FILTER (WHERE revenue_event.event_type = 'new') FROM gasp.revenue_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30')), 0))) AS DECIMAL) / NULLIF((((CAST((COALESCE((SELECT SUM(subscription.mrr) FILTER (WHERE subscription.subscription_status = 'active') FROM gasp.subscription WHERE snapshot_date = DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(((SELECT COUNT(DISTINCT customer.customer_id) FILTER (WHERE customer.customer_status = 'active') FROM gasp.customer WHERE snapshot_date = DATE '2026-06-30')), 0))) * ((CAST((COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'infrastructure') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0), 0)))), 0))) AS value
  UNION ALL
  -- gasp_gross_margin (direct): (sum(field.revenue) - sum(field.cost where field.cost_function = 'infrastructure')) / sum(field.revenue)
  SELECT 'gasp_gross_margin' AS metric, ((CAST((COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'infrastructure') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0), 0))) AS value
  UNION ALL
  -- gasp_gross_margin_o (direct): (sum(field.revenue) - sum(field.cost where field.cost_function = 'infrastructure') - sum(field.cost where field.cost_function in ('support', 'success_engineering', 'implementation', 'onboarding'))) / sum(field.revenue)
  SELECT 'gasp_gross_margin_o' AS metric, ((CAST(((COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'infrastructure') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function IN ('support', 'success_engineering', 'implementation', 'onboarding')) FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0), 0))) AS value
  UNION ALL
  -- gasp_gross_margin_m (direct): (sum(field.revenue) - sum(field.cost where field.cost_function = 'infrastructure')) / sum(field.revenue)
  SELECT 'gasp_gross_margin_m' AS metric, ((CAST((COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0) - COALESCE((SELECT SUM(cost_event.cost) FILTER (WHERE cost_event.cost_function = 'infrastructure') FROM gasp.cost_event WHERE event_date >= DATE '2026-01-01' AND event_date <= DATE '2026-06-30'), 0)) AS DECIMAL) / NULLIF(COALESCE((SELECT SUM(financials.revenue) FROM gasp.financials WHERE period_start >= DATE '2026-01-01' AND period_start <= DATE '2026-06-30'), 0), 0))) AS value
  UNION ALL
  -- gasp_rule_of_40 (staged): (metric.arr - lag(metric.arr, 1 year)) / lag(metric.arr, 1 year) + metric.ebitda_margin
  SELECT 'gasp_rule_of_40' AS metric, (SELECT value FROM (SELECT p.period_start, p.period_end, (((CAST((((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = p.period_end AND subscription_status = 'active')) * 12)) - ((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = (((p.period_end + INTERVAL '1 day') - INTERVAL '1 year') - INTERVAL '1 day') AND subscription_status = 'active')) * 12))) AS DOUBLE PRECISION) / NULLIF(((((SELECT COALESCE(SUM(mrr), 0) FROM gasp.subscription WHERE snapshot_date = (((p.period_end + INTERVAL '1 day') - INTERVAL '1 year') - INTERVAL '1 day') AND subscription_status = 'active')) * 12)), 0)) + ((CAST((SELECT COALESCE(SUM(ebitda), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end) AS DOUBLE PRECISION) / NULLIF(((SELECT COALESCE(SUM(revenue), 0) FROM gasp.financials WHERE period_start >= p.period_start AND period_start <= p.period_end)), 0))))) AS value FROM gasp.period_spine p) AS s WHERE period_start = DATE '2026-01-01') AS value
) AS demo
ORDER BY metric;
